/**
 * theme.js - 医疗健康风格主题配置
 *
 * 采用清新、专业、可信赖的医疗健康设计语言：
 * - 白色 + 浅蓝 + 青绿色主色调
 * - 高可读性、呼吸感留白
 * - 柔和圆角、微阴影层次
 */

// ─── 色彩体系 ──────────────────────────────────────────

export const colors = {
  // 背景色
  background: '#F8FAFB',        // 主背景：浅灰白
  surface: '#FFFFFF',            // 卡片表面：纯白
  surfaceAlt: '#F0F4F8',        // 替代表面：浅灰蓝

  // 主色 - 安全/健康
  primary: '#00C9A7',            // 青绿色：安全、健康
  primaryLight: '#E6FAF5',      // 主色浅底
  primaryDark: '#00A88A',       // 主色深色

  // 心率/医疗色
  medical: '#4A90D9',            // 医疗蓝：专业、可信
  medicalLight: '#E8F1FB',      // 医疗蓝浅底

  // 语义色
  safe: '#00C9A7',              // 安全：青绿
  warning: '#FFB347',           // 警告：柔和橙
  danger: '#FF6B6B',            // 危险：柔和红
  info: '#5B9BD5',              // 信息：蓝色

  // 文字色
  textPrimary: '#2D3748',       // 主文字：深灰
  textSecondary: '#718096',     // 次要文字：中灰
  textTertiary: '#A0AEC0',      // 辅助文字：浅灰
  textInverse: '#FFFFFF',       // 反色文字：白色

  // 边框/分割
  border: '#E2E8F0',            // 边框色
  divider: '#EDF2F7',           // 分割线

  // 阴影
  shadow: 'rgba(0, 0, 0, 0.08)',
  shadowLight: 'rgba(0, 0, 0, 0.04)',
}

// ─── 渐变色 ──────────────────────────────────────────

export const gradients = {
  // 安全状态渐变
  safe: ['#00C9A7', '#00D4AA'],
  // 心率渐变
  heartRate: ['#4A90D9', '#5BA0E9'],
  // 步数环渐变
  steps: ['#00C9A7', '#4A90D9'],
  // 危险渐变
  danger: ['#FF6B6B', '#FF8E8E'],
  // 警告渐变
  warning: ['#FFB347', '#FFC875'],
  // 背景渐变
  background: ['#F8FAFB', '#F0F4F8'],
}

// ─── 圆角 ──────────────────────────────────────────

export const radius = {
  xs: 4,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 20,
  xxl: 24,
  full: 9999,
}

// ─── 阴影 ──────────────────────────────────────────

export const shadows = {
  sm: '0 1px 3px rgba(0, 0, 0, 0.06)',
  md: '0 2px 8px rgba(0, 0, 0, 0.08)',
  lg: '0 4px 16px rgba(0, 0, 0, 0.1)',
  xl: '0 8px 24px rgba(0, 0, 0, 0.12)',
}

// ─── 间距 ──────────────────────────────────────────

export const spacing = {
  xs: 4,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 20,
  xxl: 24,
}

// ─── 字体大小（基础值，会被 watch-face.js 的 fs() 缩放）──

export const fontSize = {
  xs: 10,
  sm: 12,
  md: 14,
  lg: 16,
  xl: 18,
  xxl: 24,
  display: 32,
  hero: 48,
}

// ─── 主题对象 ──────────────────────────────────────────

export const theme = {
  colors,
  gradients,
  radius,
  shadows,
  spacing,
  fontSize,
}

// ─── 获取状态色 ──────────────────────────────────────

/**
 * 根据状态获取对应颜色
 * @param {string} status - 'safe' | 'warning' | 'danger' | 'info'
 * @returns {string} 颜色值
 */
export function getStatusColor(status) {
  return colors[status] || colors.info
}

/**
 * 获取心率区间颜色
 * @param {number} hr - 心率值
 * @returns {string} 颜色值
 */
export function getHeartRateColor(hr) {
  if (hr <= 100) return colors.safe
  if (hr <= 140) return colors.warning
  return colors.danger
}

/**
 * 获取心率区间标签
 * @param {number} hr - 心率值
 * @returns {object} { label, color }
 */
export function getHeartRateZone(hr) {
  if (hr < 60) return { label: '静息', color: colors.info }
  if (hr < 100) return { label: '正常', color: colors.safe }
  if (hr < 140) return { label: '偏高', color: colors.warning }
  return { label: '危险', color: colors.danger }
}

/**
 * 生成渐变色字符串（用于 canvas）
 * @param {string[]} colors - 颜色数组
 * @param {number} angle - 角度（度）
 * @returns {string} CSS 渐变字符串
 */
export function linearGradient(colorArr, angle) {
  angle = angle || 135
  return 'linear-gradient(' + angle + 'deg, ' + colorArr.join(', ') + ')'
}

export default theme

